body.script:
(function () {
    var preloader = document.getElementById('preloader');
    var seenKey = 'kiut:preloader-seen';
    var seen = false;
    try {
        seen = sessionStorage.getItem(seenKey) === '1';
    } catch (e) {
    }
    // The homepage and a reload always get the mark; only moving on through the site skips it.
    var navigation = performance.getEntriesByType ? performance.getEntriesByType('navigation')[0] : null;
    var reloaded = navigation ? navigation.type === 'reload' : false;
    if (preloader.hasAttribute('data-home') || reloaded) seen = false;
    if (seen) preloader.classList.add('preloader--quick');

    // This runs once the stylesheets are in, i.e. when the preloader first shows.
    var shownAt = Date.now();
    var minShown = seen ? 0 : 1200;
    var hidden = false;
    var settled = false;

    function hide() {
        if (hidden) return;
        hidden = true;
        try {
            sessionStorage.setItem(seenKey, '1');
        } catch (e) {
        }
        preloader.classList.add('is-done');
        setTimeout(function () {
            preloader.remove();
        }, 700);
    }

    function settle() {
        if (settled) return;
        settled = true;
        setTimeout(hide, Math.max(0, minShown - (Date.now() - shownAt)));
    }

    function hideWhenSettled() {
        // Fonts and the high-priority image would otherwise swap in after the reveal,
        // but on a slow connection they are not worth more than a short wait.
        setTimeout(settle, seen ? 300 : 1000);
        var waits = [];
        if (document.fonts && document.fonts.ready) waits.push(document.fonts.ready);
        var hero = document.querySelector('img[fetchpriority="high"]');
        if (hero && !hero.complete) {
            waits.push(new Promise(function (done) {
                hero.addEventListener('load', done);
                hero.addEventListener('error', done);
            }));
        }
        Promise.all(waits).then(settle);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', hideWhenSettled);
    } else {
        hideWhenSettled();
    }
    setTimeout(hide, seen ? 1500 : 3000);
})();

